## 二、Document 类：面向用户的 API 入口

`Document` 是用户直接操作的高层对象，它是 `DocumentPart` 的薄包装层。

```python
# docx/api.py + docx/document.py

def open(docx=None):
    """
    用户入口函数：docx.Document('file.docx')
    """
    docx = _default_docx_path() if docx is None else docx
    document_part = Package.open(docx).main_document_part
    if document_part.content_type != CT.WML_DOCUMENT_MAIN:
        tmpl = "file '%s' is not a Word file, content type is '%s'"
        raise ValueError(tmpl % (docx, document_part.content_type))
    return document_part.document
```

```python
# docx/document.py（简化）
class Document(ElementProxy):
    """
    用户可见的 Document 对象。
    ElementProxy 表示它内部持有一个 lxml Element（CT_Document）。
    """

    def __init__(self, element, part):
        super().__init__(element)  # element = CT_Document（<w:document>）
        self.__body = None
        self._part = part          # 持有 DocumentPart 的引用

    # ── 添加内容的便捷方法 ──────────────────────────────────

    def add_paragraph(self, text='', style=None):
        """在文档末尾添加段落"""
        return self.paragraphs[-1]._p.addnext(
            # 实际上委托给 _Body
        )
        # 简化表示，实际调用：
        return self._body.add_paragraph(text, style)

    def add_heading(self, text='', level=1):
        """添加标题段落（Heading 1 ~ Heading 9）"""
        style = 'Heading %d' % level
        return self.add_paragraph(text, style)

    def add_table(self, rows, cols, style=None):
        """添加表格"""
        table = self._body.add_table(rows, cols, self._block_width)
        table.style = self.styles[style] if style else None
        return table

    def add_picture(self, image_path_or_stream, width=None, height=None):
        """在文档末尾的段落中嵌入图片"""
        return self.add_paragraph().add_run().add_picture(
            image_path_or_stream, width, height
        )

    def add_page_break(self):
        """添加分页符"""
        return self._body.add_page_break()

    def add_section(self, start_type=WD_SECTION.NEW_PAGE):
        """添加新节（Section）"""
        new_sectPr = self._body._sectPr.clone()
        # 在前一段落中插入 sectPr，触发新节开始
        ...

    # ── 内容访问属性 ────────────────────────────────────────

    @property
    def paragraphs(self):
        """Body 直接子段落列表（不含表格内段落）"""
        return self._body.paragraphs

    @property
    def tables(self):
        """Body 直接子表格列表"""
        return self._body.tables

    @property
    def sections(self):
        """节列表（Sections 对象）"""
        return Sections(self._element.body, self._part)

    @property
    def styles(self):
        """文档样式库（委托给 StylesPart）"""
        return self._part.styles

    @property
    def inline_shapes(self):
        """所有内联图形"""
        return InlineShapes(self._body._body, self._part)

    @property
    def core_properties(self):
        """文档核心元数据（作者、日期等）"""
        return self._part.core_properties

    @property
    def settings(self):
        """文档设置（来自 settings.xml）"""
        return self._part.settings

    # ── 内部属性 ────────────────────────────────────────────

    @property
    def _body(self):
        """懒加载 _Body 对象（封装 <w:body> 元素）"""
        if self.__body is None:
            self.__body = _Body(self._element.body, self._part)
        return self.__body

    @property
    def _block_width(self):
        """计算正文区域宽度（用于表格默认宽度）"""
        section = self.sections[-1]
        return Emu(
            section.page_width
            - section.left_margin
            - section.right_margin
        )
```

