## 四、Section 系统

`<w:body>` 中最后一个 `<w:sectPr>` 定义了整个文档的全局节属性，而每一段的 `<w:pPr><w:sectPr>` 则标志该段之后另起一节。

### 4.1 document.xml 中的节结构

```xml
<w:body>
  <!-- 第一节内容 -->
  <w:p>
    <w:pPr>
      <!-- 注意：sectPr 在段落的 pPr 内，表示本段是上一节的最后一段 -->
      <w:sectPr>
        <w:pgSz w:w="12240" w:h="15840"/>  <!-- 页面尺寸（单位：twips） -->
        <w:pgMar w:top="1440" w:right="1800"
                 w:bottom="1440" w:left="1800"/>
        <w:headerReference w:type="default" r:id="rId2"/>
        <w:footerReference w:type="default" r:id="rId3"/>
        <w:type w:val="nextPage"/>  <!-- 节开始方式 -->
      </w:sectPr>
    </w:pPr>
  </w:p>

  <!-- 第二节内容 -->
  <w:p>...</w:p>

  <!-- body 结尾的全局 sectPr（最后一节） -->
  <w:sectPr>
    <w:pgSz w:w="12240" w:h="15840"/>
    <w:pgMar w:top="1440" w:right="1800"
             w:bottom="1440" w:left="1800"/>
  </w:sectPr>
</w:body>
```

### 4.2 Sections 对象

```python
# docx/section.py
class Sections:
    """文档所有节的集合，支持迭代和索引访问"""

    def __init__(self, body_elm, document_part):
        self._body = body_elm
        self._document_part = document_part

    def __iter__(self):
        # 每个含 sectPr 的段落，加上 body 末尾的全局 sectPr
        for sectPr in self._body.iter_sectPrs():
            yield Section(sectPr, self._document_part)

    def __len__(self):
        return len(list(self._body.iter_sectPrs()))

    def __getitem__(self, idx):
        return list(self)[idx]
```

### 4.3 Section 对象：页面布局的核心

```python
class Section:
    """单个节的页面属性封装"""

    def __init__(self, sectPr, document_part):
        self._sectPr = sectPr
        self._document_part = document_part

    # ── 页面尺寸（单位：Emu，内部用 twips 存储）──

    @property
    def page_width(self):
        """页面宽度（Emu 对象，支持 .inches/.cm/.mm 属性）"""
        return Emu(self._sectPr.page_width)

    @page_width.setter
    def page_width(self, value):
        self._sectPr.page_width = Emu(value).twips  # 转换为 twips 写 XML

    @property
    def page_height(self):
        return Emu(self._sectPr.page_height)

    # ── 页边距 ──

    @property
    def left_margin(self):
        return Emu(self._sectPr.left_margin)

    @property
    def right_margin(self):
        return Emu(self._sectPr.right_margin)

    @property
    def top_margin(self):
        return Emu(self._sectPr.top_margin)

    @property
    def bottom_margin(self):
        return Emu(self._sectPr.bottom_margin)

    # ── 页面方向 ──

    @property
    def orientation(self):
        """WD_ORIENT.PORTRAIT 或 WD_ORIENT.LANDSCAPE"""
        return self._sectPr.orientation

    @orientation.setter
    def orientation(self, value):
        """
        设置横向时，自动交换宽高值
        """
        current = self._sectPr.orientation
        if value == current:
            return
        # 交换宽高
        new_width, new_height = self._sectPr.page_height, self._sectPr.page_width
        self._sectPr.orientation = value
        self._sectPr.page_width = new_width
        self._sectPr.page_height = new_height

    # ── 节类型 ──

    @property
    def start_type(self):
        """WD_SECTION_START 枚举：NEW_PAGE / ODD_PAGE / EVEN_PAGE / CONTINUOUS"""
        return self._sectPr.start_type

    # ── 页眉页脚 ──

    @property
    def header(self):
        """默认页眉（_Header 对象）"""
        return _Header(self._sectPr, self._document_part)

    @property
    def footer(self):
        """默认页脚（_Footer 对象）"""
        return _Footer(self._sectPr, self._document_part)

    @property
    def different_first_page_header_footer(self):
        """首页是否使用不同的页眉页脚"""
        return self._sectPr.titlePg_val

    @different_first_page_header_footer.setter
    def different_first_page_header_footer(self, value):
        self._sectPr.titlePg_val = value
```

