## 二、Paragraph 类深度解析

```python
# docx/text/paragraph.py
class Paragraph(ElementProxy):
    """
    封装 <w:p> 元素。
    继承 ElementProxy：self._element 就是 CT_P（<w:p>）的 lxml 元素。
    """

    def __init__(self, p, parent):
        super().__init__(p, parent)
        self._p = self._element  # 别名，方便使用

    # ── 文本访问 ──────────────────────────────────────────────

    @property
    def text(self):
        """
        段落的纯文本（拼接所有 Run 的文字）。
        注意：只读，写入请用 clear() + add_run()。
        """
        return ''.join(run.text for run in self.runs)

    @text.setter
    def text(self, text):
        """
        直接赋值：清空段落内容，添加一个新 Run。
        不推荐：会丢失原有格式。
        """
        p = self._p
        p.clear_content()
        r = p.add_r()
        r.text = text

    @property
    def runs(self):
        """
        该段落的所有 Run 对象列表。
        注意：只包含 <w:r>，不包含超链接内的 run（需遍历 hyperlinks）。
        """
        return [Run(r, self) for r in self._p.r_lst]

    # ── 添加内容 ──────────────────────────────────────────────

    def add_run(self, text=None, style=None):
        """
        在段落末尾添加一个新 Run。
        如果 text 不为 None，则同时设置文字。
        """
        r = self._p.add_r()
        run = Run(r, self)
        if text is not None:
            run.text = text
        if style is not None:
            run.style = self.part.styles[style]
        return run

    def insert_paragraph_before(self, text=None, style=None):
        """在本段落之前插入一个新段落（返回新段落）"""
        p = self._p.addprevious(CT_P.new())
        paragraph = Paragraph(p, self._parent)
        if text is not None:
            paragraph.add_run(text)
        if style is not None:
            paragraph.style = style
        return paragraph

    def clear(self):
        """删除段落内所有 Run（保留段落格式 pPr）"""
        self._p.clear_content()
        return self

    # ── 样式 ──────────────────────────────────────────────────

    @property
    def style(self):
        """
        段落样式（_ParagraphStyle 对象）。
        从 pStyle 元素读取样式名，再从 document 的 Styles 库中查找。
        """
        style_id = self._pPr.pStyle_val  # 读取 <w:pStyle w:val="...">
        if style_id is None:
            return self.part.styles.default('paragraph')
        return self.part.styles.get_by_id(style_id, WD_STYLE_TYPE.PARAGRAPH)

    @style.setter
    def style(self, style_or_name):
        """
        设置段落样式：
        - 传入 Style 对象 → 直接使用
        - 传入字符串     → 从 styles 库查找
        - 传入 None      → 重置为 Normal
        """
        style = self.part.styles._get_style_id_from_name(style_or_name, WD_STYLE_TYPE.PARAGRAPH)
        self._pPr.pStyle_val = style

    # ── 段落格式 ──────────────────────────────────────────────

    @property
    def paragraph_format(self):
        """ParagraphFormat 对象（封装 <w:pPr>）"""
        return ParagraphFormat(self._p)

    # ── 对齐（快捷方式）──────────────────────────────────────

    @property
    def alignment(self):
        """WD_ALIGN_PARAGRAPH 枚举（LEFT/CENTER/RIGHT/JUSTIFY 等）"""
        pPr = self._p.pPr
        if pPr is None:
            return None
        return pPr.jc_val

    @alignment.setter
    def alignment(self, value):
        self._p.get_or_add_pPr().jc_val = value

    # ── 超链接 ──────────────────────────────────────────────

    @property
    def hyperlinks(self):
        """段落中所有超链接（Hyperlink 对象列表）"""
        return [Hyperlink(hl, self) for hl in self._p.hl_lst]

    # ── 内部属性 ──────────────────────────────────────────────

    @property
    def _pPr(self):
        """懒加载 <w:pPr>（不存在则创建）"""
        return self._p.get_or_add_pPr()

    @property
    def contains_page_break(self):
        """段落中是否含有分页符"""
        return self._p.contains_page_break
