## 三、ParagraphFormat：段落格式的完整封装

`ParagraphFormat` 封装 `<w:pPr>`，控制段落的所有排版属性。

```python
# docx/text/parfmt.py
class ParagraphFormat(ElementProxy):
    """
    封装 <w:pPr>（段落属性）元素。
    所有属性均实现了继承解析：
      - 本段明确设置 → 使用本段值
      - 未设置 → 从段落样式继承
      - 样式未设置 → 从基样式继承（链式向上）
      - 最终 → 文档默认值
    """

    def __init__(self, paragraph_element):
        super().__init__(paragraph_element)
        self._p = paragraph_element

    # ── 对齐 ──────────────────────────────────────────────────

    @property
    def alignment(self):
        """WD_ALIGN_PARAGRAPH: LEFT=0, CENTER=1, RIGHT=2, JUSTIFY=3 等"""
        pPr = self._p.pPr
        if pPr is None:
            return None
        return pPr.jc_val

    @alignment.setter
    def alignment(self, value):
        self._p.get_or_add_pPr().jc_val = value

    # ── 缩进 ──────────────────────────────────────────────────

    @property
    def left_indent(self):
        """左缩进（Length 对象，如 Inches(0.5)）"""
        pPr = self._p.pPr
        if pPr is None or pPr.ind is None:
            return None
        return Emu(pPr.ind.left or 0)

    @left_indent.setter
    def left_indent(self, value):
        # 转换为 twips（1/20 磅）写入 XML
        self._p.get_or_add_pPr().get_or_add_ind().left = Emu(value).twips

    @property
    def right_indent(self):
        pPr = self._p.pPr
        if pPr is None or pPr.ind is None:
            return None
        return Emu(pPr.ind.right or 0)

    @property
    def first_line_indent(self):
        """
        首行缩进（正值）或悬挂缩进（负值）。
        XML 中：正数 → <w:ind w:firstLine="...">
                负数 → <w:ind w:hanging="...">（绝对值）
        """
        pPr = self._p.pPr
        if pPr is None or pPr.ind is None:
            return None
        # 内部逻辑自动处理正负转换
        return Emu(pPr.ind.firstLine_or_hanging)

    # ── 段间距 ────────────────────────────────────────────────

    @property
    def space_before(self):
        """段前间距（Length 对象）"""
        pPr = self._p.pPr
        if pPr is None or pPr.spacing is None:
            return None
        return Emu(pPr.spacing.before or 0)

    @space_before.setter
    def space_before(self, value):
        self._p.get_or_add_pPr().get_or_add_spacing().before = Emu(value).twips

    @property
    def space_after(self):
        """段后间距（Length 对象）"""
        pPr = self._p.pPr
        if pPr is None or pPr.spacing is None:
            return None
        return Emu(pPr.spacing.after or 0)

    # ── 行距 ──────────────────────────────────────────────────

    @property
    def line_spacing(self):
        """
        行距值：
        - 返回 Length 对象 → 固定行距或最小行距（单位 EMU）
        - 返回 float      → 多倍行距（如 1.5 = 1.5倍）
        - 返回 None       → 继承自样式
        """
        pPr = self._p.pPr
        if pPr is None or pPr.spacing is None:
            return None
        return pPr.spacing.line_spacing

    @property
    def line_spacing_rule(self):
        """
        WD_LINE_SPACING:
          AT_LEAST   = 'atLeast'  → 最小行距
          EXACTLY    = 'exact'    → 固定行距
          MULTIPLE   = 'auto'     → 多倍行距（默认）
        """
        pPr = self._p.pPr
        if pPr is None or pPr.spacing is None:
            return None
        return pPr.spacing.lineRule

    # ── 分页控制 ──────────────────────────────────────────────

    @property
    def keep_with_next(self):
        """与下段同页（True/False/None）"""
        return self._get_pPr_bool_attr('keepNext')

    @keep_with_next.setter
    def keep_with_next(self, value):
        self._set_pPr_bool_attr('keepNext', value)

    @property
    def keep_together(self):
        """段内不分页"""
        return self._get_pPr_bool_attr('keepLines')

    @property
    def page_break_before(self):
        """段前分页"""
        return self._get_pPr_bool_attr('pageBreakBefore')

    @property
    def widow_control(self):
        """孤行控制（防止段落首/尾行单独出现在页面上）"""
        return self._get_pPr_bool_attr('widowControl')

    # ── 制表位 ──────────────────────────────────────────────

    @property
    def tab_stops(self):
        """TabStops 对象（管理段落的自定义制表位列表）"""
        pPr = self._p.pPr
        if pPr is None:
            return TabStops(CT_PPr.new())
        return TabStops(pPr)
