## 四、Run 类深度解析

`Run` 是段落内连续格式相同的文字片段，对应 `<w:r>` 元素。

```python
# docx/text/run.py
class Run(ElementProxy):
    """封装 <w:r>（Run）元素"""

    def __init__(self, r, parent):
        super().__init__(r, parent)
        self._r = self._element

    # ── 文字 ──────────────────────────────────────────────────

    @property
    def text(self):
        """
        Run 内所有 <w:t> 的文字拼接。
        特殊元素：
          <w:br>       → '\\n'（换行/分页/换列）
          <w:tab>      → '\\t'
          <w:cr>       → '\\n'（回车，等同于软回车）
          <w:noBreakHyphen> → '-'（不断行连字符）
        """
        return self._r.text

    @text.setter
    def text(self, text):
        """
        设置 Run 文字：
        1. 清除所有现有 <w:t>/<w:br>/<w:tab> 等内容元素
        2. 创建新的 <w:t>，设置 xml:space="preserve"（如含空格）
        """
        self._r.text = text

    # ── 字体格式（快捷访问）──────────────────────────────────

    @property
    def bold(self):
        """
        粗体：True/False/None。
        None 表示"继承自段落样式或字符样式"。
        底层：读取/写入 <w:rPr><w:b/> 元素的存在性。
        """
        return self.font.bold

    @bold.setter
    def bold(self, value):
        self.font.bold = value

    @property
    def italic(self):
        return self.font.italic

    @italic.setter
    def italic(self, value):
        self.font.italic = value

    @property
    def underline(self):
        """
        下划线：
          True          → 单线下划线（<w:u w:val="single">）
          False         → 无下划线（<w:u w:val="none">）
          None          → 继承
          WD_UNDERLINE.* → 特定样式（双线、波浪线等）
        """
        return self.font.underline

    @underline.setter
    def underline(self, value):
        self.font.underline = value

    # ── 字符样式 ──────────────────────────────────────────────

    @property
    def style(self):
        """字符样式（CharacterStyle 对象）"""
        style_id = self._r.style
        if style_id is None:
            return self.part.styles.default('character')
        return self.part.styles.get_by_id(style_id, WD_STYLE_TYPE.CHARACTER)

    @style.setter
    def style(self, style_or_name):
        style_id = self.part.styles._get_style_id_from_name(
            style_or_name, WD_STYLE_TYPE.CHARACTER
        )
        self._r.style = style_id

    # ── Font 对象 ──────────────────────────────────────────────

    @property
    def font(self):
        """Font 对象（封装 <w:rPr>，提供所有字符级格式）"""
        return Font(self._r, self.part.styles)

    # ── 特殊元素插入 ──────────────────────────────────────────

    def add_break(self, break_type=WD_BREAK.LINE):
        """
        插入换行符：
          WD_BREAK.LINE        → <w:br/>（软回车，段内换行）
          WD_BREAK.PAGE        → <w:br w:type="page"/>（分页符）
          WD_BREAK.COLUMN      → <w:br w:type="column"/>（换列）
          WD_BREAK.LINE_CLEAR_LEFT  → 清除左浮动后换行
          WD_BREAK.LINE_CLEAR_RIGHT → 清除右浮动后换行
        """
        type_attr, clear_attr = {
            WD_BREAK.LINE:              (None,     None),
            WD_BREAK.PAGE:              ('page',   None),
            WD_BREAK.COLUMN:            ('column', None),
            WD_BREAK.LINE_CLEAR_LEFT:   (None,     'left'),
            WD_BREAK.LINE_CLEAR_RIGHT:  (None,     'right'),
        }[break_type]
        br = CT_Br.new(type_attr, clear_attr)
        self._r._r.append(br)

    def add_picture(self, image_path_or_stream, width=None, height=None):
        """
        在 Run 内嵌入图片（内联图形）。
        详见"图片系统"章节。
        """
        inline = self.part.new_pic_inline(image_path_or_stream, width, height)
        self._r._r.append(CT_Drawing.new(inline))
        return InlineShape(inline)

    def add_tab(self):
        """插入 <w:tab/>（制表符）"""
        self._r._r.append(CT_Tab.new())

    # ── 大小写与效果 ──────────────────────────────────────────

    @property
    def all_caps(self):
        return self.font.all_caps

    @property
    def small_caps(self):
        return self.font.small_caps

    @property
    def strike(self):
        return self.font.strike

    @property
    def double_strike(self):
        return self.font.double_strike
