## 五、Font 类：字符级格式的完整封装

`Font` 封装 `<w:rPr>`（Run Properties），是所有字符格式属性的统一入口。

```python
# docx/text/font.py
class Font(ElementProxy):
    """
    封装 <w:rPr>（Run属性）。
    同时支持 Run 级别和字符样式级别的格式设置。
    """

    def __init__(self, element, theme_color_map=None):
        super().__init__(element)
        self._element = element  # CT_R 或 CT_RPr

    @property
    def _rPr(self):
        """懒加载 <w:rPr>，不存在则创建"""
        return self._element.get_or_add_rPr()

    # ── 字体名称 ──────────────────────────────────────────────

    @property
    def name(self):
        """
        字体名称（str 或 None）。
        底层对应 <w:rFonts w:ascii="...">。
        同时设置 ascii/hAnsi/eastAsia/cs 四个属性（全平台兼容）。
        """
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.rFonts_ascii

    @name.setter
    def name(self, value):
        """
        设置字体时，python-docx 实际上会同时设置：
          <w:rFonts w:ascii="Arial"
                    w:hAnsi="Arial"
                    w:eastAsia="Arial"
                    w:cs="Arial"/>
        """
        self._rPr.set_font(value)

    # ── 字号 ──────────────────────────────────────────────────

    @property
    def size(self):
        """
        字号（Length 对象，单位 EMU）。
        XML 中存储为半磅（half-points）：
          <w:sz w:val="24"/> → 12pt
          Pt(12) → sz_val = 24
        """
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.sz_val  # 返回 Length 或 None

    @size.setter
    def size(self, value):
        if value is None:
            self._rPr.sz = None
            self._rPr.szCs = None
        else:
            # 转换为半磅（half-points）
            half_points = Pt(value).pt * 2
            self._rPr.sz_val = int(half_points)
            self._rPr.szCs_val = int(half_points)  # 复杂脚本字体同步

    # ── 粗体/斜体 ──────────────────────────────────────────────

    @property
    def bold(self):
        """
        True/False/None 三值语义：
          True  → 强制粗体（<w:b/>）
          False → 强制非粗体（<w:b w:val="0"/>）
          None  → 继承（删除 <w:b> 元素）
        """
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.b_val

    @bold.setter
    def bold(self, value):
        self._rPr.b_val = value  # CT_RPr 处理 None/True/False 到 XML 的转换

    @property
    def italic(self):
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.i_val

    @italic.setter
    def italic(self, value):
        self._rPr.i_val = value

    # ── 颜色 ──────────────────────────────────────────────────

    @property
    def color(self):
        """ColorFormat 对象（封装 <w:color>）"""
        return ColorFormat(self._element)

    # ── 下划线 ──────────────────────────────────────────────────

    @property
    def underline(self):
        """
        True                → WD_UNDERLINE.SINGLE（单下划线）
        False               → WD_UNDERLINE.NONE
        None                → 继承
        WD_UNDERLINE.*      → 具体样式
        """
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.u_val  # CT_RPr 将 XML val 映射到枚举

    # ── 删除线 ──────────────────────────────────────────────────

    @property
    def strike(self):
        """单删除线"""
        return self._get_rPr_bool('strike')

    @property
    def double_strike(self):
        """双删除线"""
        return self._get_rPr_bool('dstrike')

    # ── 位置与大小调整 ────────────────────────────────────────

    @property
    def subscript(self):
        """下标"""
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.vertAlign_val == WD_VERT_ALIGN.SUBSCRIPT

    @property
    def superscript(self):
        """上标"""
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.vertAlign_val == WD_VERT_ALIGN.SUPERSCRIPT

    # ── 特殊效果 ──────────────────────────────────────────────

    @property
    def all_caps(self):
        """全部大写显示（不改变存储的文字）"""
        return self._get_rPr_bool('caps')

    @property
    def small_caps(self):
        """小号大写显示"""
        return self._get_rPr_bool('smallCaps')

    @property
    def hidden(self):
        """隐藏文字（不打印、不显示，除非开启"显示所有格式标记"）"""
        return self._get_rPr_bool('vanish')

    @property
    def highlight_color(self):
        """高亮颜色（WD_COLOR_INDEX 枚举：YELLOW/CYAN/PINK 等）"""
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.highlight_val

    @property
    def shadow(self):
        """文字阴影"""
        return self._get_rPr_bool('shadow')

    @property
    def outline(self):
        """文字轮廓"""
        return self._get_rPr_bool('outline')

    @property
    def emboss(self):
        """浮雕效果"""
        return self._get_rPr_bool('emboss')

    @property
    def imprint(self):
        """印压效果"""
        return self._get_rPr_bool('imprint')

    # ── 内部通用方法 ──────────────────────────────────────────

    def _get_rPr_bool(self, tag_localname):
        rPr = self._element.rPr
        if rPr is None:
            return None
        elm = rPr.find(qn('w:' + tag_localname))
        if elm is None:
            return None
        val = elm.get(qn('w:val'))
        if val is None:
            return True      # 元素存在但无 val 属性 → True
        if val in ('0', 'false'):
            return False
        return True
