## 六、ColorFormat：颜色系统

```python
# docx/dml/color.py
class ColorFormat:
    """
    封装颜色设置，支持三种颜色模式：
      1. RGB 颜色（十六进制，如 "#FF0000"）
      2. 主题颜色（ThemeColor 枚举，依赖文档主题）
      3. 继承（None）
    """

    def __init__(self, rPr_parent):
        self._element = rPr_parent

    @property
    def type(self):
        """
        WD_COLOR_TYPE:
          RGB   → 明确的 RGB 颜色
          THEME → 主题颜色
          None  → 继承
        """
        rPr = self._element.rPr
        if rPr is None or rPr.color is None:
            return None
        color = rPr.color
        if color.themeColor is not None:
            return WD_COLOR_TYPE.THEME
        if color.val is not None:
            return WD_COLOR_TYPE.RGB
        return None

    @property
    def rgb(self):
        """
        RGBColor 对象（int 子类，值为 0xRRGGBB）。
        调用示例：
          font.color.rgb           → RGBColor(0x1F, 0x4E, 0x79)
          str(font.color.rgb)      → '1F4E79'
          font.color.rgb.red       → 31
        """
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.color.val

    @rgb.setter
    def rgb(self, value):
        """
        value: RGBColor 对象 或 0xRRGGBB 整数
        写入 <w:color w:val="1F4E79"/>
        """
        self._element.get_or_add_rPr().get_or_add_color().val = value

    @property
    def theme_color(self):
        """MSO_THEME_COLOR 枚举（ACCENT_1 ~ ACCENT_6, BACKGROUND_1/2 等）"""
        rPr = self._element.rPr
        if rPr is None:
            return None
        return rPr.color.themeColor

    @theme_color.setter
    def theme_color(self, value):
        self._element.get_or_add_rPr().get_or_add_color().themeColor = value


class RGBColor(int):
    """
    RGB 颜色，继承自 int（值为 0xRRGGBB）。
    支持 str(color) → '1F4E79' 格式。
    """

    def __new__(cls, r, g, b):
        return super().__new__(cls, (r << 16) + (g << 8) + b)

    def __str__(self):
        return '%06X' % self

    @property
    def red(self):
        return (self >> 16) & 0xFF

    @property
    def green(self):
        return (self >> 8) & 0xFF

    @property
    def blue(self):
        return self & 0xFF

    @classmethod
    def from_string(cls, rgb_hex_str):
        """从 '1F4E79' 这样的字符串构造"""
        r = int(rgb_hex_str[:2], 16)
        g = int(rgb_hex_str[2:4], 16)
        b = int(rgb_hex_str[4:], 16)
        return cls(r, g, b)
