一个包含丰富格式的段落在 XML 中的完整样子：

```xml
<w:p>
  <!-- 段落属性 (ParagraphFormat) -->
  <w:pPr>
    <w:pStyle w:val="BodyText"/>         ← 段落样式
    <w:jc w:val="both"/>                 ← 两端对齐
    <w:spacing w:before="120"
               w:after="120"
               w:line="360"
               w:lineRule="auto"/>       ← 1.5倍行距
    <w:ind w:left="720" w:firstLine="360"/> ← 左缩进+首行缩进
    <w:keepNext/>                        ← 与下段同页
    <w:rPr>                              ← 段落标记的字符格式
      <w:lang w:val="zh-CN"/>
    </w:rPr>
  </w:pPr>

  <!-- Run #1：普通文字 -->
  <w:r>
    <w:rPr>
      <w:rStyle w:val="Emphasis"/>       ← 字符样式
      <w:b/>                             ← 粗体
      <w:color w:val="1F4E79"/>          ← 颜色
      <w:sz w:val="28"/>                 ← 14pt (28/2)
    </w:rPr>
    <w:t>重要内容：</w:t>
  </w:r>

  <!-- Run #2：带高亮的文字 -->
  <w:r>
    <w:rPr>
      <w:highlight w:val="yellow"/>      ← 黄色高亮
    </w:rPr>
    <w:t xml:space="preserve"> 注意这里 </w:t>
  </w:r>

  <!-- 软回车（段内换行） -->
  <w:r>
    <w:br/>
  </w:r>

  <!-- 超链接 -->
  <w:hyperlink r:id="rId5"
               w:history="1">
    <w:r>
      <w:rPr>
        <w:rStyle w:val="Hyperlink"/>
      </w:rPr>
      <w:t>点击访问</w:t>
    </w:r>
  </w:hyperlink>

  <!-- 制表符 -->
  <w:r>
    <w:tab/>
    <w:t>制表符后的内容</w:t>
  </w:r>
</w:p>
```

