## 八、实战：操作段落与 Run 的最佳实践

```python
import docx
from docx.shared import Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
from docx.enum.dml import MSO_THEME_COLOR

doc = docx.Document()

# 1. 创建格式丰富的段落
para = doc.add_paragraph()
pf = para.paragraph_format
pf.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY       # 两端对齐
pf.left_indent = Cm(1)                           # 左缩进 1cm
pf.first_line_indent = Cm(0.75)                  # 首行缩进 0.75cm
pf.space_before = Pt(6)                          # 段前 6pt
pf.space_after = Pt(6)                           # 段后 6pt
pf.line_spacing = 1.5                            # 1.5 倍行距
pf.line_spacing_rule = WD_LINE_SPACING.MULTIPLE  # 多倍行距模式

# 2. 在段落中添加多个 Run
run1 = para.add_run("标题文字：")
run1.bold = True
run1.font.size = Pt(14)
run1.font.color.rgb = RGBColor(0x1F, 0x4E, 0x79)  # 深蓝色

run2 = para.add_run("正文内容，带高亮。")
run2.font.highlight_color = docx.enum.text.WD_COLOR_INDEX.YELLOW

run3 = para.add_run(" 斜体备注")
run3.italic = True
run3.font.size = Pt(10)
run3.font.color.theme_color = MSO_THEME_COLOR.ACCENT_3

# 3. 插入换行符（软回车，不新建段落）
run3.add_break()

run4 = para.add_run("换行后继续的内容")
run4.font.name = "Courier New"  # 代码字体

# 4. 遍历段落内容
for run in para.runs:
    print(f"  Run: {run.text!r}")
    print(f"    bold={run.bold}, size={run.font.size}")

# 5. 直接操作 XML（高级用法）
from docx.oxml.ns import qn
p_element = para._p                    # lxml Element
rPr_list = p_element.findall('.//' + qn('w:rPr'))
print(f"共有 {len(rPr_list)} 个 rPr 元素")
```

